import { gateway } from '../infra/gateway';
import { orders } from '../infra/orders';

export async function partialRefund(orderId: string, amountMinor: number): Promise<string> {
  const order = await orders.find(orderId);
  if (amountMinor > order.total) {
    throw new Error('refund exceeds order total');
  }
  return gateway.refund(order.transactionId, amountMinor);
}
